typedef struct { size_t end; node_t *node; int state; } cell_t;  /* state: EMPTY/OK/FAIL */

static cell_t *memo;      /* calloc(n_rules * (len + 1), sizeof *memo) */
static size_t   ncols;    /* len + 1 */

cell_t parse_rule(rule_id r, size_t pos) {
    cell_t *c = &memo[(size_t)r * ncols + pos];
    if (c->state != EMPTY) return *c;            /* hit: success or recorded failure */
    *c = rule_impl[r](pos);                      /* ordinary backtracking body */
    if (c->state == EMPTY) c->state = FAIL;      /* failures are cached too */
    return *c;
}
